add("Loaders","Gravity Balls","\n<canvas id=\"XGRV\" width=\"160\" height=\"90\" style=\"width:160px;height:90px;\"></canvas>\n<script>(function(){\n  var id='XGRV',c=document.getElementById(id);\n  if(!c)return;var ctx=c.getContext('2d'),W=160,H=90;\n  var B=[{x:30,y:30,vx:2,vy:0,r:10,col:'#00f5d4'},{x:80,y:20,vx:-1.5,vy:1,r:8,col:'#7b5cff'},{x:130,y:40,vx:-2,vy:.5,r:9,col:'#ff2d78'},{x:60,y:60,vx:1,vy:-1.5,r:7,col:'#ffaa00'}];\n  function tick(){\n    ctx.clearRect(0,0,W,H);\n    B.forEach(function(b){\n      b.vy+=.15;b.x+=b.vx;b.y+=b.vy;\n      if(b.x<b.r||b.x>W-b.r)b.vx*=-.92;\n      if(b.y<b.r){b.vy*=-.8;b.y=b.r;}\n      if(b.y>H-b.r){b.vy*=-.82;b.y=H-b.r;}\n      ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,6.28);ctx.fillStyle=b.col;ctx.shadowBlur=14;ctx.shadowColor=b.col;ctx.fill();ctx.shadowBlur=0;\n    });\n    requestAnimationFrame(tick);\n  }\n  tick();\n})();<\\/script>","gravityBalls");

add("Loaders","Fibonacci Spiral","\n<canvas id=\"XFIB\" width=\"120\" height=\"120\" style=\"width:120px;height:120px;\"></canvas>\n<script>(function(){\n  var id='XFIB',c=document.getElementById(id);\n  if(!c)return;var ctx=c.getContext('2d'),phi=(1+Math.sqrt(5))/2,t=0;\n  function draw(){\n    ctx.clearRect(0,0,120,120);ctx.save();ctx.translate(60,60);\n    var grad=ctx.createLinearGradient(-50,-50,50,50);\n    grad.addColorStop(0,'#00f5d4');grad.addColorStop(.5,'#7b5cff');grad.addColorStop(1,'#ff2d78');\n    ctx.strokeStyle=grad;ctx.lineWidth=2;ctx.shadowBlur=6;ctx.shadowColor='#7b5cff';ctx.beginPath();\n    for(var i=0;i<300;i++){\n      var angle=i*0.1+t,r=2*Math.pow(phi,angle/(2*Math.PI));\n      var x=r*Math.cos(angle),y=r*Math.sin(angle);\n      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);\n    }\n    ctx.stroke();ctx.restore();t+=.018;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","fibSpiral");

