add("Switches","Cyber Toggle","\n<div style=\"display:inline-flex;flex-direction:column;align-items:center;gap:8px;padding:10px;\">\n  <style>\n    .ctw input{display:none;}\n    .ctw .ctr{width:64px;height:32px;background:#111;border-radius:16px;position:relative;cursor:pointer;transition:all .35s;box-shadow:0 0 0 2px #333,inset 0 0 8px #000;}\n    .ctw .cth{position:absolute;top:4px;left:4px;width:24px;height:24px;border-radius:50%;background:#333;transition:all .38s cubic-bezier(.3,1.5,.7,1);box-shadow:0 2px 5px rgba(0,0,0,.5);}\n    .ctw .cgw{position:absolute;inset:0;border-radius:16px;background:linear-gradient(90deg,#00f5d4,#7b5cff);opacity:0;transition:opacity .35s;}\n    .ctw input:checked~.ctr{box-shadow:0 0 0 2px #00f5d4,inset 0 0 8px rgba(0,245,212,.1),0 0 16px rgba(0,245,212,.2);}\n    .ctw input:checked~.ctr .cgw{opacity:.4;}\n    .ctw input:checked~.ctr .cth{left:36px;background:#00f5d4;}\n  </style>\n  <label class=\"ctw\" for=\"XCTG\">\n    <input type=\"checkbox\" id=\"XCTG\" checked>\n    <div class=\"ctr\"><div class=\"cgw\"></div><div class=\"cth\"></div></div>\n  </label>\n  <div style=\"display:flex;gap:24px;font-family:monospace;font-size:10px;letter-spacing:1px;\">\n    <span style=\"color:#666;\">OFF</span><span style=\"color:#00f5d4;\">ON</span>\n  </div>\n</div>","cyberToggle");

