add("Cards","Holographic Tilt","\n<div id=\"XHLT\" style=\"width:170px;height:105px;border-radius:14px;background:linear-gradient(135deg,#0d1120,#1a1a2e);border:1px solid rgba(255,255,255,.08);position:relative;overflow:hidden;cursor:pointer;transition:transform .1s;display:flex;align-items:center;justify-content:center;\">\n  <style>@keyframes holoa{to{transform:rotate(360deg)}}</style>\n  <div style=\"position:absolute;inset:-60%;background:conic-gradient(from 0deg,rgba(0,245,212,.18),rgba(123,92,255,.18),rgba(255,45,120,.18),rgba(0,245,212,.18));animation:holoa 6s linear infinite;border-radius:50%;\"></div>\n  <div style=\"position:absolute;inset:1px;background:#0d1120;border-radius:13px;\"></div>\n  <div style=\"position:relative;z-index:1;text-align:center;\"><div style=\"font-size:26px;margin-bottom:4px;\">&#10022;</div><div style=\"font-family:monospace;font-size:10px;color:#7b8ab8;letter-spacing:2px;\">HOLOGRAPHIC</div></div>\n</div>\n<script>(function(){\n  var c=document.getElementById('XHLT');if(!c)return;\n  c.addEventListener('mousemove',function(e){var r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform='perspective(600px) rotateY('+x*28+'deg) rotateX('+(-y*28)+'deg)';});\n  c.addEventListener('mouseleave',function(){c.style.transform='none';});\n})();<\\/script>","holoTilt");

