add("Navigation","Breadcrumb","\n<div style=\"display:flex;align-items:center;gap:4px;font-family:monospace;font-size:11px;flex-wrap:wrap;\">\n  <span style=\"color:#556080;cursor:pointer;padding:3px 8px;border-radius:6px;\" onmouseover=\"this.style.color='#7b5cff'\" onmouseout=\"this.style.color='#556080'\">Home</span>\n  <span style=\"color:#2a3050;\">&#8250;</span>\n  <span style=\"color:#556080;cursor:pointer;padding:3px 8px;border-radius:6px;\" onmouseover=\"this.style.color='#7b5cff'\" onmouseout=\"this.style.color='#556080'\">Components</span>\n  <span style=\"color:#2a3050;\">&#8250;</span>\n  <span style=\"color:#556080;cursor:pointer;padding:3px 8px;border-radius:6px;\" onmouseover=\"this.style.color='#7b5cff'\" onmouseout=\"this.style.color='#556080'\">Loaders</span>\n  <span style=\"color:#2a3050;\">&#8250;</span>\n  <span style=\"color:#00f5d4;padding:3px 8px;border-radius:6px;background:rgba(0,245,212,.08);border:1px solid rgba(0,245,212,.2);\">DNA Helix</span>\n</div>","breadcrumb");

add("Science","Wave Interference","\n<canvas id=\"XWVI\" width=\"180\" height=\"90\" style=\"width:180px;height:90px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XWVI');if(!c)return;\n  var ctx=c.getContext('2d'),t=0,W=180,H=90;\n  function draw(){\n    ctx.clearRect(0,0,W,H);\n    var grad=ctx.createLinearGradient(0,0,W,0);\n    grad.addColorStop(0,'#00f5d4');grad.addColorStop(.5,'#7b5cff');grad.addColorStop(1,'#ff2d78');\n    ctx.strokeStyle=grad;ctx.lineWidth=2.5;ctx.shadowBlur=8;ctx.shadowColor='#7b5cff';ctx.beginPath();\n    for(var x=0;x<W;x++){\n      var y1=20*Math.sin(x*.05+t),y2=15*Math.sin(x*.08-t*1.3),y3=10*Math.sin(x*.12+t*.7),y=H/2+y1+y2+y3;\n      if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);\n    }\n    ctx.stroke();t+=.04;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","waveInterference");

add("Science","Lorenz Attractor","\n<canvas id=\"XLRZ\" width=\"160\" height=\"120\" style=\"width:160px;height:120px;background:#000;border-radius:8px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XLRZ');if(!c)return;\n  var ctx=c.getContext('2d'),x=.1,y=0,z=0,s=10,r=28,b=8/3,dt=.008,pts=[],MAX=400;\n  function draw(){\n    for(var i=0;i<3;i++){var dx=s*(y-x),dy=x*(r-z)-y,dz=x*y-b*z;x+=dx*dt;y+=dy*dt;z+=dz*dt;pts.push({x:x,y:z});if(pts.length>MAX)pts.shift();}\n    ctx.clearRect(0,0,160,120);ctx.beginPath();\n    pts.forEach(function(p,i){var px=p.x*3.5+80,py=p.y*-2.5+110;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);});\n    var grad=ctx.createLinearGradient(0,0,160,120);grad.addColorStop(0,'#00f5d4');grad.addColorStop(1,'#ff2d78');\n    ctx.strokeStyle=grad;ctx.lineWidth=1.2;ctx.stroke();requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","lorenz");

add("Science","Fourier Circles","\n<canvas id=\"XFOU\" width=\"160\" height=\"130\" style=\"width:160px;height:130px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XFOU');if(!c)return;\n  var ctx=c.getContext('2d'),t=0,cx=65,cy=65,trail=[];\n  var W=[{r:30,f:1},{r:15,f:3},{r:8,f:5},{r:5,f:7}];\n  function draw(){\n    ctx.clearRect(0,0,160,130);var x=cx,y=cy;\n    W.forEach(function(w){\n      var nx=x+w.r*Math.cos(w.f*t),ny=y+w.r*Math.sin(w.f*t);\n      ctx.beginPath();ctx.arc(x,y,w.r,0,6.28);ctx.strokeStyle='rgba(123,92,255,.25)';ctx.lineWidth=1;ctx.stroke();\n      ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(nx,ny);ctx.strokeStyle='rgba(0,245,212,.7)';ctx.lineWidth=2;ctx.stroke();\n      x=nx;y=ny;\n    });\n    trail.push({x:x,y:y});if(trail.length>200)trail.shift();\n    ctx.beginPath();trail.forEach(function(p,i){if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);});\n    ctx.strokeStyle='#ff2d78';ctx.lineWidth=2;ctx.shadowBlur=6;ctx.shadowColor='#ff2d78';ctx.stroke();ctx.shadowBlur=0;\n    t+=.04;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","fourier");

add("Science","Double Pendulum","\n<canvas id=\"XDBL\" width=\"180\" height=\"150\" style=\"width:180px;height:150px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XDBL');if(!c)return;\n  var ctx=c.getContext('2d'),ox=90,oy=20,L1=50,L2=45,m1=1,m2=1,g=9.8;\n  var a1=Math.PI/2,a2=Math.PI/4,v1=0,v2=0,trail=[];\n  function step(){\n    var num1=-g*(2*m1+m2)*Math.sin(a1)-m2*g*Math.sin(a1-2*a2)-2*Math.sin(a1-a2)*m2*(v2*v2*L2+v1*v1*L1*Math.cos(a1-a2));\n    var den1=L1*(2*m1+m2-m2*Math.cos(2*a1-2*a2));\n    var num2=2*Math.sin(a1-a2)*((m1+m2)*v1*v1*L1+(m1+m2)*g*Math.cos(a1)+m2*v2*v2*L2*Math.cos(a1-a2));\n    var den2=L2*(2*m1+m2-m2*Math.cos(2*a1-2*a2));\n    v1+=num1/den1*.04;v2+=num2/den2*.04;a1+=v1*.04;a2+=v2*.04;v1*=.999;v2*=.999;\n  }\n  function draw(){\n    step();step();\n    var x1=ox+Math.sin(a1)*L1,y1=oy+Math.cos(a1)*L1,x2=x1+Math.sin(a2)*L2,y2=y1+Math.cos(a2)*L2;\n    trail.push({x:x2,y:y2});if(trail.length>120)trail.shift();\n    ctx.clearRect(0,0,180,150);\n    ctx.beginPath();trail.forEach(function(p,i){if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);});\n    ctx.strokeStyle='rgba(255,45,120,.4)';ctx.lineWidth=1.5;ctx.stroke();\n    ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle='rgba(0,245,212,.7)';ctx.lineWidth=2;ctx.stroke();\n    [ox,x1,x2].forEach(function(px,i){var py=[oy,y1,y2][i];ctx.beginPath();ctx.arc(px,py,[5,8,8][i],0,6.28);ctx.fillStyle=['#7b5cff','#00f5d4','#ff2d78'][i];ctx.shadowBlur=12;ctx.shadowColor=ctx.fillStyle;ctx.fill();ctx.shadowBlur=0;});\n    requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","doublePendulum");

add("Science","Vector Field","\n<canvas id=\"XVEC\" width=\"160\" height=\"100\" style=\"width:160px;height:100px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XVEC');if(!c)return;\n  var ctx=c.getContext('2d'),t=0,step=20;\n  function hsl(h,s,l,a){return 'hsla('+h+','+s+'%,'+l+'%,'+a+')';}\n  function draw(){\n    ctx.clearRect(0,0,160,100);\n    for(var x=10;x<160;x+=step){\n      for(var y=10;y<100;y+=step){\n        var angle=Math.sin(x*.04+t)*Math.PI+Math.cos(y*.04-t)*.8,len=8;\n        var ex=x+Math.cos(angle)*len,ey=y+Math.sin(angle)*len;\n        var hue=((Math.atan2(ey-y,ex-x)/Math.PI+1)*180)%360;\n        ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(ex,ey);\n        ctx.strokeStyle=hsl(hue,80,60,.7);ctx.lineWidth=1.5;ctx.stroke();\n        ctx.beginPath();ctx.arc(ex,ey,2,0,6.28);ctx.fillStyle=hsl(hue,80,70,.9);ctx.fill();\n      }\n    }\n    t+=.04;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","vectorField");

add("Gaming","Health Bar","\n<div style=\"padding:14px;width:220px;\">\n  <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;\">\n    <span style=\"font-family:monospace;font-size:10px;color:#ff2d78;letter-spacing:1px;\">&#10084; HEALTH</span>\n    <span id=\"XHBV\" style=\"font-family:monospace;font-size:10px;color:#ff2d78;\">78 / 100</span>\n  </div>\n  <div style=\"height:14px;background:rgba(255,0,0,.1);border-radius:7px;overflow:hidden;border:1px solid rgba(255,45,120,.2);\">\n    <div id=\"XHBB\" style=\"height:100%;width:78%;background:linear-gradient(90deg,#ff2d78,#ff6060);border-radius:7px;transition:width .5s;box-shadow:0 0 10px rgba(255,45,120,.5);\"></div>\n  </div>\n  <div style=\"display:flex;gap:8px;margin-top:10px;justify-content:center;\">\n    <button onclick=\"var b=document.getElementById('XHBB'),v=document.getElementById('XHBV'),p=parseFloat(b.style.width)||78;p=Math.max(0,p-15);b.style.width=p+'%';v.textContent=Math.round(p)+' / 100';b.style.background=p<30?'linear-gradient(90deg,#f00,#f44)':p<60?'linear-gradient(90deg,#f60,#f90)':'linear-gradient(90deg,#ff2d78,#ff6060)';\" style=\"padding:4px 12px;border:1px solid rgba(255,45,120,.3);background:transparent;color:#ff2d78;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">- HIT</button>\n    <button onclick=\"var b=document.getElementById('XHBB'),v=document.getElementById('XHBV'),p=parseFloat(b.style.width)||78;p=Math.min(100,p+20);b.style.width=p+'%';v.textContent=Math.round(p)+' / 100';b.style.background='linear-gradient(90deg,#ff2d78,#ff6060)';\" style=\"padding:4px 12px;border:1px solid rgba(0,245,212,.3);background:transparent;color:#00f5d4;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">+ HEAL</button>\n  </div>\n</div>","healthBar");

add("Gaming","Score Counter","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:10px;padding:14px;\">\n  <div style=\"font-family:monospace;font-size:9px;letter-spacing:3px;color:#4a5580;\">SCORE</div>\n  <div id=\"XSCV\" style=\"font-family:'Orbitron',monospace,sans-serif;font-size:36px;font-weight:900;color:#ffcc00;text-shadow:0 0 20px rgba(255,204,0,.5);transition:all .2s;letter-spacing:2px;\">000000</div>\n  <div style=\"display:flex;gap:6px;\">\n    <button onclick=\"var el=document.getElementById('XSCV'),v=parseInt(el.textContent)||0;v+=100;el.textContent=String(v).padStart(6,'0');el.style.transform='scale(1.1)';el.style.color='#fff';setTimeout(function(){el.style.transform='scale(1)';el.style.color='#ffcc00';},200);\" style=\"padding:4px 10px;border:1px solid rgba(255,204,0,.2);background:transparent;color:#ffcc00;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">+100</button>\n    <button onclick=\"var el=document.getElementById('XSCV'),v=parseInt(el.textContent)||0;v+=500;el.textContent=String(v).padStart(6,'0');el.style.transform='scale(1.1)';el.style.color='#fff';setTimeout(function(){el.style.transform='scale(1)';el.style.color='#ffcc00';},200);\" style=\"padding:4px 10px;border:1px solid rgba(255,204,0,.2);background:transparent;color:#ffcc00;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">+500</button>\n    <button onclick=\"var el=document.getElementById('XSCV'),v=parseInt(el.textContent)||0;v+=1000;el.textContent=String(v).padStart(6,'0');el.style.transform='scale(1.1)';el.style.color='#fff';setTimeout(function(){el.style.transform='scale(1)';el.style.color='#ffcc00';},200);\" style=\"padding:4px 10px;border:1px solid rgba(255,204,0,.2);background:transparent;color:#ffcc00;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">+1000</button>\n  </div>\n</div>","scoreCounter");

add("Gaming","D-Pad","\n<div style=\"display:flex;flex-direction:column;align-items:center;padding:10px;gap:8px;\">\n  <div style=\"display:grid;grid-template-columns:repeat(3,36px);grid-template-rows:repeat(3,36px);gap:3px;\">\n    <div></div>\n    <div id=\"XDPu\" onclick=\"document.getElementById('XDPd2').textContent='UP'\" style=\"background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;color:#7b8ab8;cursor:pointer;transition:all .1s;user-select:none;\" onmousedown=\"this.style.background='linear-gradient(135deg,#7b5cff,#00f5d4)'\" onmouseup=\"this.style.background='rgba(255,255,255,.06)'\" onmouseleave=\"this.style.background='rgba(255,255,255,.06)'\">&#9650;</div>\n    <div></div>\n    <div id=\"XDPl\" onclick=\"document.getElementById('XDPd2').textContent='LEFT'\" style=\"background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;color:#7b8ab8;cursor:pointer;transition:all .1s;user-select:none;\" onmousedown=\"this.style.background='linear-gradient(135deg,#7b5cff,#00f5d4)'\" onmouseup=\"this.style.background='rgba(255,255,255,.06)'\" onmouseleave=\"this.style.background='rgba(255,255,255,.06)'\">&#9664;</div>\n    <div onclick=\"document.getElementById('XDPd2').textContent='PRESS'\" style=\"background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;color:#7b8ab8;cursor:pointer;transition:all .1s;user-select:none;\" onmousedown=\"this.style.background='linear-gradient(135deg,#7b5cff,#00f5d4)'\" onmouseup=\"this.style.background='rgba(255,255,255,.06)'\" onmouseleave=\"this.style.background='rgba(255,255,255,.06)'\">&#9679;</div>\n    <div onclick=\"document.getElementById('XDPd2').textContent='RIGHT'\" style=\"background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;color:#7b8ab8;cursor:pointer;transition:all .1s;user-select:none;\" onmousedown=\"this.style.background='linear-gradient(135deg,#7b5cff,#00f5d4)'\" onmouseup=\"this.style.background='rgba(255,255,255,.06)'\" onmouseleave=\"this.style.background='rgba(255,255,255,.06)'\">&#9654;</div>\n    <div></div>\n    <div onclick=\"document.getElementById('XDPd2').textContent='DOWN'\" style=\"background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;color:#7b8ab8;cursor:pointer;transition:all .1s;user-select:none;\" onmousedown=\"this.style.background='linear-gradient(135deg,#7b5cff,#00f5d4)'\" onmouseup=\"this.style.background='rgba(255,255,255,.06)'\" onmouseleave=\"this.style.background='rgba(255,255,255,.06)'\">&#9660;</div>\n    <div></div>\n  </div>\n  <div id=\"XDPd2\" style=\"font-family:monospace;font-size:10px;color:#4a5580;letter-spacing:2px;min-height:16px;\"></div>\n</div>","dPad");

add("Inputs","Neon Input","\n<div style=\"display:flex;flex-direction:column;gap:6px;padding:10px;width:200px;\">\n  <label style=\"font-family:monospace;font-size:9px;letter-spacing:2px;color:#7b5cff;text-transform:uppercase;\">USERNAME</label>\n  <div style=\"position:relative;\">\n    <input id=\"XNIN\" type=\"text\" placeholder=\"type here...\" style=\"width:100%;padding:10px 14px;background:rgba(0,0,0,.4);border:1px solid rgba(123,92,255,.3);border-radius:8px;color:#fff;font-family:monospace;font-size:12px;outline:none;transition:all .3s;\">\n    <div id=\"XNINl\" style=\"position:absolute;bottom:0;left:50%;width:0;height:2px;background:linear-gradient(90deg,#7b5cff,#00f5d4);border-radius:2px;transition:all .35s;transform:translateX(-50%);\"></div>\n  </div>\n</div>\n<script>(function(){\n  var inp=document.getElementById('XNIN'),line=document.getElementById('XNINl');if(!inp)return;\n  inp.addEventListener('focus',function(){inp.style.borderColor='rgba(123,92,255,.7)';inp.style.boxShadow='0 0 16px rgba(123,92,255,.2)';line.style.width='100%';});\n  inp.addEventListener('blur',function(){inp.style.borderColor='rgba(123,92,255,.3)';inp.style.boxShadow='none';line.style.width='0';});\n})();<\\/script>","neonInput");

add("Inputs","OTP Code","\n<div style=\"display:flex;gap:8px;padding:10px;justify-content:center;\">\n  <style>\n    .otp{width:38px;height:46px;background:rgba(0,0,0,.4);border:2px solid rgba(123,92,255,.25);border-radius:10px;text-align:center;color:#fff;font-family:monospace;font-size:18px;font-weight:700;outline:none;transition:all .25s;caret-color:#7b5cff;}\n    .otp:focus{border-color:#7b5cff;box-shadow:0 0 14px rgba(123,92,255,.3);background:rgba(123,92,255,.05);}\n    .otp.filled{border-color:#00f5d4;background:rgba(0,245,212,.04);}\n  </style>\n  <input class=\"otp\" maxlength=\"1\" type=\"text\" inputmode=\"numeric\">\n  <input class=\"otp\" maxlength=\"1\" type=\"text\" inputmode=\"numeric\">\n  <input class=\"otp\" maxlength=\"1\" type=\"text\" inputmode=\"numeric\">\n  <input class=\"otp\" maxlength=\"1\" type=\"text\" inputmode=\"numeric\">\n  <input class=\"otp\" maxlength=\"1\" type=\"text\" inputmode=\"numeric\">\n  <input class=\"otp\" maxlength=\"1\" type=\"text\" inputmode=\"numeric\">\n</div>\n<script>(function(){\n  var inputs=[].slice.call(document.querySelectorAll('.otp'));\n  inputs.forEach(function(inp,i){\n    inp.addEventListener('input',function(e){inp.value=inp.value.replace(/\\D/g,'');inp.classList.toggle('filled',inp.value!=='');if(inp.value&&i<inputs.length-1)inputs[i+1].focus();});\n    inp.addEventListener('keydown',function(e){if(e.key==='Backspace'&&!inp.value&&i>0)inputs[i-1].focus();});\n  });\n})();<\\/script>","otpInput");

add("Inputs","Star Rating","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px;padding:10px;\">\n  <div id=\"XSTR2\" style=\"display:flex;gap:4px;cursor:pointer;\">\n    <div data-v=\"1\" style=\"font-size:28px;transition:all .2s;filter:grayscale(1);opacity:.4;transform:scale(.9);\">&#11088;</div>\n    <div data-v=\"2\" style=\"font-size:28px;transition:all .2s;filter:grayscale(1);opacity:.4;transform:scale(.9);\">&#11088;</div>\n    <div data-v=\"3\" style=\"font-size:28px;transition:all .2s;filter:grayscale(1);opacity:.4;transform:scale(.9);\">&#11088;</div>\n    <div data-v=\"4\" style=\"font-size:28px;transition:all .2s;filter:grayscale(1);opacity:.4;transform:scale(.9);\">&#11088;</div>\n    <div data-v=\"5\" style=\"font-size:28px;transition:all .2s;filter:grayscale(1);opacity:.4;transform:scale(.9);\">&#11088;</div>\n  </div>\n  <div id=\"XSTR2l\" style=\"font-family:monospace;font-size:9px;color:#4a5580;letter-spacing:2px;\">RATE THIS</div>\n</div>\n<script>(function(){\n  var wrap=document.getElementById('XSTR2'),lb=document.getElementById('XSTR2l');if(!wrap)return;\n  var stars=[].slice.call(wrap.children),labels=['TERRIBLE','BAD','OKAY','GOOD','AMAZING!'],selected=0;\n  function paint(n,hover){stars.forEach(function(s,i){if(i<n){s.style.filter='none';s.style.opacity='1';s.style.transform='scale(1.1)';s.style.color=hover?'#ffcc00':'#ffaa00';s.style.textShadow=hover?'0 0 12px #ffcc00':'0 0 8px #ffaa00';}else{s.style.filter='grayscale(1)';s.style.opacity='.35';s.style.transform='scale(.9)';s.style.color='';s.style.textShadow='';}});}\n  stars.forEach(function(s){\n    s.addEventListener('mouseenter',function(){var v=+s.dataset.v;paint(v,true);lb.textContent=labels[v-1];lb.style.color='#ffcc00';});\n    s.addEventListener('mouseleave',function(){paint(selected,false);lb.textContent=selected?labels[selected-1]:'RATE THIS';lb.style.color=selected?'#ffaa00':'#4a5580';});\n    s.addEventListener('click',function(){selected=+s.dataset.v;paint(selected,false);lb.textContent=labels[selected-1];lb.style.color='#ffaa00';});\n  });\n})();<\\/script>","starRating");

add("Inputs","Neon Slider","\n<div style=\"padding:16px 20px;width:220px;\">\n  <div style=\"display:flex;justify-content:space-between;margin-bottom:10px;\">\n    <span style=\"font-family:monospace;font-size:9px;letter-spacing:2px;color:#4a5580;\">INTENSITY</span>\n    <span id=\"XSLV\" style=\"font-family:monospace;font-size:12px;color:#00f5d4;font-weight:700;\">65%</span>\n  </div>\n  <style>.nsldr{-webkit-appearance:none;appearance:none;width:100%;height:4px;border-radius:2px;background:rgba(255,255,255,.08);outline:none;}.nsldr::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#00f5d4,#7b5cff);cursor:pointer;box-shadow:0 0 12px rgba(0,245,212,.6);transition:transform .2s;}.nsldr::-webkit-slider-thumb:hover{transform:scale(1.2);}</style>\n  <input type=\"range\" class=\"nsldr\" id=\"XSLR\" min=\"0\" max=\"100\" value=\"65\">\n</div>\n<script>(function(){\n  var s=document.getElementById('XSLR'),v=document.getElementById('XSLV');if(!s)return;\n  function upd(){var pct=s.value+'%';v.textContent=pct;s.style.background='linear-gradient(90deg,#00f5d4 '+pct+',rgba(255,255,255,.08) '+pct+')';}\n  s.addEventListener('input',upd);upd();\n})();<\\/script>","neonSlider");

add("Clocks","Analog Clock","\n<canvas id=\"XACL\" width=\"120\" height=\"120\" style=\"width:120px;height:120px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XACL');if(!c)return;\n  var ctx=c.getContext('2d'),cx=60,cy=60,R=54;\n  function draw(){\n    var now=new Date(),h=now.getHours()%12,m=now.getMinutes(),s=now.getSeconds(),ms=now.getMilliseconds();\n    ctx.clearRect(0,0,120,120);\n    ctx.beginPath();ctx.arc(cx,cy,R,0,6.28);ctx.fillStyle='#0d1120';ctx.fill();ctx.strokeStyle='rgba(0,245,212,.25)';ctx.lineWidth=2;ctx.stroke();\n    for(var i=0;i<12;i++){var a=i/12*6.28-1.57,x1=cx+Math.cos(a)*(R-6),y1=cy+Math.sin(a)*(R-6),x2=cx+Math.cos(a)*(R-2),y2=cy+Math.sin(a)*(R-2);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=i%3===0?'rgba(0,245,212,.6)':'rgba(0,245,212,.2)';ctx.lineWidth=i%3===0?2:1;ctx.stroke();}\n    var ha=(h+m/60)/12*6.28-1.57;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(ha)*30,cy+Math.sin(ha)*30);ctx.strokeStyle='#dde4f8';ctx.lineWidth=3;ctx.lineCap='round';ctx.stroke();\n    var ma=(m+s/60)/60*6.28-1.57;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(ma)*40,cy+Math.sin(ma)*40);ctx.strokeStyle='#00f5d4';ctx.lineWidth=2;ctx.lineCap='round';ctx.stroke();\n    var sa=(s+ms/1000)/60*6.28-1.57;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(sa)*44,cy+Math.sin(sa)*44);ctx.strokeStyle='#ff2d78';ctx.lineWidth=1.5;ctx.lineCap='round';ctx.stroke();\n    ctx.beginPath();ctx.arc(cx,cy,4,0,6.28);ctx.fillStyle='#fff';ctx.fill();\n  }\n  setInterval(draw,50);draw();\n})();<\\/script>","analogClock");

add("Clocks","Digital Clock","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px;\">\n  <div id=\"XDCT\" style=\"font-family:'Orbitron',monospace,sans-serif;font-size:30px;font-weight:700;color:#00f5d4;text-shadow:0 0 20px rgba(0,245,212,.5);letter-spacing:3px;\"></div>\n  <div id=\"XDCD\" style=\"font-family:monospace;font-size:9px;color:#4a5580;letter-spacing:3px;\"></div>\n  <div style=\"font-family:monospace;font-size:8px;color:#2a3050;letter-spacing:2px;\">ASIA/KOLKATA</div>\n</div>\n<script>(function(){\n  var t=document.getElementById('XDCT'),d=document.getElementById('XDCD');if(!t)return;\n  var days=['SUN','MON','TUE','WED','THU','FRI','SAT'],months=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];\n  function tick(){var n=new Date();t.textContent=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0')+':'+String(n.getSeconds()).padStart(2,'0');d.textContent=days[n.getDay()]+' '+String(n.getDate()).padStart(2,'0')+' '+months[n.getMonth()]+' '+n.getFullYear();}\n  setInterval(tick,500);tick();\n})();<\\/script>","digitalClock");

add("Clocks","Binary Clock","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:10px;padding:14px;\">\n  <canvas id=\"XBCL\" width=\"150\" height=\"70\" style=\"width:150px;height:70px;\"></canvas>\n  <div style=\"font-family:monospace;font-size:8px;color:#2a3050;letter-spacing:2px;\">BINARY CLOCK H\u00b7M\u00b7S</div>\n</div>\n<script>(function(){\n  var c=document.getElementById('XBCL');if(!c)return;var ctx=c.getContext('2d');\n  function draw(){\n    var now=new Date(),vals=[now.getHours(),now.getMinutes(),now.getSeconds()];\n    ctx.clearRect(0,0,150,70);\n    vals.forEach(function(v,col){\n      var bits=v.toString(2).padStart(6,'0');\n      bits.split('').forEach(function(b,row){\n        var x=20+col*40,y=5+row*10;\n        ctx.fillStyle=b==='1'?['#00f5d4','#7b5cff','#ff2d78'][col]:'rgba(255,255,255,.06)';\n        ctx.shadowBlur=b==='1'?8:0;ctx.shadowColor=ctx.fillStyle;\n        ctx.beginPath();ctx.rect(x,y,8,8);ctx.fill();ctx.shadowBlur=0;\n      });\n    });\n  }\n  setInterval(draw,500);draw();\n})();<\\/script>","binaryClock");

add("Anime FX","Sakura Petals","\n<div id=\"XSAK\" style=\"width:200px;height:120px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 0%,rgba(255,100,150,.08),transparent 70%);border-radius:12px;border:1px solid rgba(255,100,150,.12);\">\n  <style>@keyframes sak{0%{transform:translateY(-20px) rotate(0deg);opacity:0}10%{opacity:1}100%{transform:translateY(130px) rotate(360deg);opacity:0}}</style>\n</div>\n<script>(function(){\n  var wrap=document.getElementById('XSAK');if(!wrap)return;\n  var petals=['&#127800;','&#127914;','&#127806;','&#127804;'];\n  function spawn(){\n    var p=document.createElement('div');\n    p.style.cssText='position:absolute;font-size:'+(10+Math.random()*12)+'px;left:'+(Math.random()*180)+'px;top:-20px;animation:sak '+(2+Math.random()*3)+'s ease-in forwards;pointer-events:none;';\n    p.innerHTML=petals[Math.floor(Math.random()*petals.length)];\n    wrap.appendChild(p);setTimeout(function(){p.remove();},5000);\n  }\n  var iv=setInterval(spawn,300);spawn();spawn();spawn();\n})();<\\/script>","sakuraPetals");

add("Anime FX","Energy Aura","\n<div style=\"display:flex;justify-content:center;align-items:center;height:130px;position:relative;\">\n  <style>\n    @keyframes aura1{0%,100%{transform:scale(1);opacity:.5}50%{transform:scale(1.15);opacity:.8}}\n    @keyframes aura2{0%,100%{transform:scale(1.1) rotate(0deg);opacity:.4}50%{transform:scale(1.25) rotate(180deg);opacity:.7}}\n    @keyframes aura3{0%{transform:scale(1.2) rotate(0deg)}100%{transform:scale(1.2) rotate(360deg)}}\n  </style>\n  <div style=\"position:relative;width:70px;height:70px;display:flex;align-items:center;justify-content:center;\">\n    <div style=\"position:absolute;inset:-20px;border-radius:50%;background:radial-gradient(circle,rgba(123,92,255,.35),transparent 70%);animation:aura1 2s ease-in-out infinite;\"></div>\n    <div style=\"position:absolute;inset:-12px;border-radius:50%;border:2px solid rgba(0,245,212,.3);animation:aura2 3s ease-in-out infinite;\"></div>\n    <div style=\"position:absolute;inset:-18px;border-radius:50%;border:1px dashed rgba(255,45,120,.4);animation:aura3 4s linear infinite;\"></div>\n    <div style=\"width:50px;height:50px;border-radius:50%;background:radial-gradient(circle,#fff 10%,#00f5d4 40%,rgba(123,92,255,.8) 70%,transparent);box-shadow:0 0 30px rgba(123,92,255,.6),0 0 60px rgba(0,245,212,.3);display:flex;align-items:center;justify-content:center;font-size:22px;\">&#9889;</div>\n  </div>\n</div>","energyAura");

add("Anime FX","Speed Lines","\n<canvas id=\"XSPD\" width=\"200\" height=\"120\" style=\"width:200px;height:120px;border-radius:12px;background:#07090f;\"></canvas>\n<script>(function(){\n  var c=document.getElementById('XSPD');if(!c)return;\n  var ctx=c.getContext('2d'),W=200,H=120,cx=W/2,cy=H/2;\n  var lines=[];for(var i=0;i<40;i++)lines.push({angle:Math.random()*Math.PI*2,len:20+Math.random()*60,speed:.5+Math.random()*2,dist:10+Math.random()*40});\n  function draw(){\n    ctx.fillStyle='rgba(7,9,15,.3)';ctx.fillRect(0,0,W,H);\n    lines.forEach(function(l){\n      l.dist+=l.speed;if(l.dist>80){l.dist=5;l.len=20+Math.random()*60;l.angle=Math.random()*Math.PI*2;}\n      var x1=cx+Math.cos(l.angle)*l.dist,y1=cy+Math.sin(l.angle)*l.dist;\n      var x2=cx+Math.cos(l.angle)*(l.dist+l.len),y2=cy+Math.sin(l.angle)*(l.dist+l.len);\n      var grad=ctx.createLinearGradient(x1,y1,x2,y2);grad.addColorStop(0,'rgba(0,245,212,0)');grad.addColorStop(1,'rgba(0,245,212,.8)');\n      ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=grad;ctx.lineWidth=1.5;ctx.stroke();\n    });\n    requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","speedLines");

add("Anime FX","Glitch Screen","\n<div id=\"XGLS\" style=\"width:180px;height:100px;background:#0d1120;border-radius:10px;overflow:hidden;position:relative;cursor:pointer;border:1px solid rgba(0,245,212,.15);\">\n  <canvas id=\"XGLSC\" width=\"180\" height=\"100\" style=\"width:180px;height:100px;display:block;\"></canvas>\n  <div style=\"position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-family:monospace;font-size:12px;color:#00f5d4;letter-spacing:3px;text-shadow:0 0 10px #00f5d4;pointer-events:none;\">CLICK ME</div>\n</div>\n<script>(function(){\n  var c=document.getElementById('XGLSC'),wrap=document.getElementById('XGLS');if(!c)return;\n  var ctx=c.getContext('2d'),W=180,H=100,glitching=false;\n  (function scanlines(){ctx.clearRect(0,0,W,H);for(var y=0;y<H;y+=3){ctx.fillStyle='rgba(0,245,212,.015)';ctx.fillRect(0,y,W,1);}requestAnimationFrame(scanlines);})();\n  wrap.addEventListener('click',function(){\n    if(glitching)return;glitching=true;var frames=0;\n    var iv=setInterval(function(){\n      ctx.clearRect(0,0,W,H);var slices=3+Math.floor(Math.random()*5);\n      for(var i=0;i<slices;i++){var sy=Math.random()*H,sh=Math.random()*20,dx=(Math.random()-.5)*30;ctx.fillStyle=Math.random()>.5?'rgba(255,0,100,.3)':'rgba(0,245,212,.3)';ctx.fillRect(dx,sy,W,sh);}\n      frames++;if(frames>8){clearInterval(iv);ctx.clearRect(0,0,W,H);glitching=false;}\n    },60);\n  });\n})();<\\/script>","glitchScreen");


