add("Loaders","Plasma Ball","\n<canvas id=\"XPLB\" width=\"120\" height=\"120\" style=\"width:120px;height:120px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XPLB\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),W=120,H=120,cx=60,cy=60,t=0;\n  function draw(){\n    ctx.clearRect(0,0,W,H);\n    var bg=ctx.createRadialGradient(cx,cy,0,cx,cy,50);\n    bg.addColorStop(0,\"rgba(123,92,255,.6)\");bg.addColorStop(1,\"rgba(7,9,15,0)\");\n    ctx.beginPath();ctx.arc(cx,cy,50,0,6.28);ctx.fillStyle=bg;ctx.fill();\n    for(var i=0;i<6;i++){\n      var a=i/6*6.28+t,r1=0,r2=40+Math.sin(t*3+i)*10;\n      var x2=cx+Math.cos(a)*r2,y2=cy+Math.sin(a)*r2;\n      var mid1x=cx+Math.cos(a+.4)*r2*.5+Math.sin(t+i)*15;\n      var mid1y=cy+Math.sin(a+.4)*r2*.5+Math.cos(t*1.3+i)*12;\n      ctx.beginPath();ctx.moveTo(cx,cy);\n      ctx.quadraticCurveTo(mid1x,mid1y,x2,y2);\n      var cols=[\"#00f5d4\",\"#7b5cff\",\"#ff2d78\",\"#ffaa00\",\"#00cc55\",\"#ff6600\"];\n      ctx.strokeStyle=cols[i];ctx.lineWidth=2;ctx.shadowBlur=12;ctx.shadowColor=cols[i];ctx.stroke();ctx.shadowBlur=0;\n    }\n    ctx.beginPath();ctx.arc(cx,cy,8,0,6.28);\n    var cg=ctx.createRadialGradient(cx,cy,0,cx,cy,8);\n    cg.addColorStop(0,\"#fff\");cg.addColorStop(1,\"#7b5cff\");\n    ctx.fillStyle=cg;ctx.shadowBlur=20;ctx.shadowColor=\"#7b5cff\";ctx.fill();ctx.shadowBlur=0;\n    t+=.025;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","plasmaball");

add("Loaders","Hypnotic Ring","\n<canvas id=\"XHYP\" width=\"110\" height=\"110\" style=\"width:110px;height:110px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XHYP\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0;\n  function hsl(h,s,l){return \"hsl(\"+h+\",\"+s+\"%,\"+l+\"%)\"}\n  function draw(){\n    ctx.clearRect(0,0,110,110);\n    for(var r=6;r<=48;r+=6){\n      ctx.beginPath();\n      var segs=Math.round(r*1.2);\n      for(var i=0;i<=segs;i++){\n        var a=i/segs*Math.PI*2+t*(r%12===0?1:-1),wave=Math.sin(a*4+t*2)*3;\n        if(i===0)ctx.moveTo(55+Math.cos(a)*(r+wave),55+Math.sin(a)*(r+wave));\n        else ctx.lineTo(55+Math.cos(a)*(r+wave),55+Math.sin(a)*(r+wave));\n      }\n      ctx.closePath();\n      var p=r/48;\n      ctx.strokeStyle=hsl(160+p*120+t*30,80,50+p*20);\n      ctx.lineWidth=1.5;ctx.stroke();\n    }\n    t+=.025;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","hypnoticRing");

add("Loaders","Magnetic Field","\n<canvas id=\"XMGF\" width=\"160\" height=\"100\" style=\"width:160px;height:100px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XMGF\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0,lines=16;\n  function draw(){\n    ctx.clearRect(0,0,160,100);\n    for(var l=0;l<lines;l++){\n      var off=l/lines*Math.PI*2;\n      ctx.beginPath();\n      for(var x=0;x<=160;x+=2){\n        var mag=Math.sin(x*.04+t+off)*20+Math.sin(x*.08-t+off)*12,y=50+mag;\n        if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);\n      }\n      var p=l/lines,r=Math.round(123+132*p),g2=Math.round(92+163*p),b2=Math.round(255-200*p);\n      ctx.strokeStyle=\"rgba(\"+r+\",\"+g2+\",\"+b2+\",\"+(0.15+p*0.35)+\")\";\n      ctx.lineWidth=1.5;ctx.stroke();\n    }\n    t+=.04;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","magneticField");

add("Loaders","Neural Web","\n<canvas id=\"XNWB\" width=\"160\" height=\"100\" style=\"width:160px;height:100px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XNWB\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),nodes=[];\n  for(var i=0;i<14;i++)nodes.push({x:Math.random()*160,y:Math.random()*100,vx:(Math.random()-.5)*.6,vy:(Math.random()-.5)*.6});\n  function tick(){\n    ctx.fillStyle=\"rgba(7,9,15,.15)\";ctx.fillRect(0,0,160,100);\n    nodes.forEach(function(n){n.x+=n.vx;n.y+=n.vy;if(n.x<4||n.x>156)n.vx*=-1;if(n.y<4||n.y>96)n.vy*=-1;});\n    for(var i=0;i<nodes.length;i++){\n      for(var j=i+1;j<nodes.length;j++){\n        var dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y,d=Math.sqrt(dx*dx+dy*dy);\n        if(d<80){\n          ctx.beginPath();ctx.moveTo(nodes[i].x,nodes[i].y);ctx.lineTo(nodes[j].x,nodes[j].y);\n          ctx.strokeStyle=\"rgba(123,92,255,\"+(1-d/80)*.6+\")\";ctx.lineWidth=1;ctx.stroke();\n        }\n      }\n    }\n    nodes.forEach(function(n){\n      ctx.beginPath();ctx.arc(n.x,n.y,3,0,6.28);ctx.fillStyle=\"#00f5d4\";\n      ctx.shadowBlur=8;ctx.shadowColor=\"#00f5d4\";ctx.fill();ctx.shadowBlur=0;\n    });\n    requestAnimationFrame(tick);\n  }\n  tick();\n})();<\\/script>","neuralWeb");

add("Loaders","String Theory","\n<canvas id=\"XSTR3\" width=\"180\" height=\"90\" style=\"width:180px;height:90px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XSTR3\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0;\n  function hsl(h,s,l,a){return \"hsla(\"+h+\",\"+s+\"%,\"+l+\"%,\"+a+\")\"}\n  function draw(){\n    ctx.clearRect(0,0,180,90);\n    for(var s=0;s<8;s++){\n      ctx.beginPath();\n      var off=s/8*Math.PI*2;\n      for(var x=0;x<=180;x+=2){\n        var y=45+Math.sin(x*.035+t+off)*18+Math.sin(x*.07-t*.8+off)*10;\n        if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);\n      }\n      ctx.strokeStyle=hsl(s*45+t*30,80,60,0.5);ctx.lineWidth=1.5;ctx.stroke();\n    }\n    t+=.035;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","stringTheory");

add("Loaders","Clockwork Gears","\n<canvas id=\"XCWG\" width=\"140\" height=\"120\" style=\"width:140px;height:120px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XCWG\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0;\n  function gear(cx,cy,r,teeth,angle,col){\n    ctx.save();ctx.translate(cx,cy);ctx.rotate(angle);\n    ctx.beginPath();\n    for(var i=0;i<teeth*2;i++){\n      var a=i/teeth*Math.PI,rr=i%2===0?r:r*.75;\n      if(i===0)ctx.moveTo(Math.cos(a)*rr,Math.sin(a)*rr);\n      else ctx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr);\n    }\n    ctx.closePath();ctx.strokeStyle=col;ctx.lineWidth=1.5;ctx.shadowBlur=8;ctx.shadowColor=col;ctx.stroke();ctx.shadowBlur=0;\n    ctx.beginPath();ctx.arc(0,0,r*.3,0,6.28);ctx.strokeStyle=col;ctx.stroke();\n    ctx.restore();\n  }\n  function draw(){\n    ctx.clearRect(0,0,140,120);\n    gear(45,55,30,10,t,\"#00f5d4\");\n    gear(95,55,20,7,-t*1.5,\"#7b5cff\");\n    gear(95,95,14,5,t*2.1,\"#ff2d78\");\n    t+=.02;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","clockworkGears");

add("Loaders","Quantum Tunnel","\n<canvas id=\"XQTN\" width=\"180\" height=\"90\" style=\"width:180px;height:90px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XQTN\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0;\n  function draw(){\n    ctx.clearRect(0,0,180,90);\n    for(var i=20;i>0;i--){\n      var s=i/20,w=180*s,h=90*s,x=(180-w)/2,y=(90-h)/2;\n      var alpha=s*.4,hue=200+i*8+t*20;\n      ctx.strokeStyle=\"hsla(\"+hue+\",80%,60%,\"+alpha+\")\";\n      ctx.lineWidth=1.5;ctx.beginPath();ctx.rect(x+Math.sin(t+i)*.5,y+Math.cos(t+i)*.5,w,h);ctx.stroke();\n    }\n    var gx=ctx.createLinearGradient(60,0,120,0);\n    gx.addColorStop(0,\"rgba(0,245,212,0)\");gx.addColorStop(.5,\"rgba(0,245,212,.8)\");gx.addColorStop(1,\"rgba(0,245,212,0)\");\n    ctx.fillStyle=gx;\n    var bx=80+Math.sin(t*2)*50;\n    ctx.fillRect(bx-4,35,8,20);\n    t+=.04;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","quantumTunnel");

add("Loaders","Liquid Metal","\n<canvas id=\"XLQM\" width=\"160\" height=\"90\" style=\"width:160px;height:90px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XLQM\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0,pts=8;\n  function draw(){\n    ctx.clearRect(0,0,160,90);\n    ctx.beginPath();\n    for(var i=0;i<=pts;i++){\n      var a=i/pts*Math.PI*2,r=35+Math.sin(t*2+i*.8)*12+Math.cos(t*1.3+i*1.2)*8;\n      var x=80+Math.cos(a)*r,y=45+Math.sin(a)*r*(0.6+Math.sin(t+i*.5)*.15);\n      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);\n    }\n    ctx.closePath();\n    var grd=ctx.createRadialGradient(75,40,0,80,45,45);\n    grd.addColorStop(0,\"rgba(180,200,255,.9)\");grd.addColorStop(.4,\"rgba(100,150,255,.6)\");grd.addColorStop(1,\"rgba(0,245,212,.2)\");\n    ctx.fillStyle=grd;ctx.fill();\n    ctx.strokeStyle=\"rgba(150,200,255,.8)\";ctx.lineWidth=2;ctx.shadowBlur=15;ctx.shadowColor=\"#00f5d4\";ctx.stroke();ctx.shadowBlur=0;\n    t+=.03;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","liquidMetal");

