add("Buttons","Binary Rain Btn","\n<div style=\"display:flex;justify-content:center;padding:10px;\">\n<button id=\"XBNB\" style=\"padding:12px 28px;background:#050a05;border:2px solid #0f0;color:#0f0;font-family:monospace;font-size:13px;font-weight:700;cursor:pointer;letter-spacing:2px;position:relative;overflow:hidden;text-transform:uppercase;transition:all .3s;\">\n  <span style=\"position:relative;z-index:1;\">MATRIX</span>\n  <canvas id=\"XBNBC\" width=\"140\" height=\"46\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;opacity:.3;pointer-events:none;\"></canvas>\n</button>\n</div>\n<script>(function(){\n  var b=document.getElementById(\"XBNB\"),cv=document.getElementById(\"XBNBC\");if(!b||!cv)return;\n  var ctx=cv.getContext(\"2d\"),cols=Math.floor(140/8),drops=[];\n  for(var i=0;i<cols;i++)drops[i]=Math.floor(Math.random()*20);\n  setInterval(function(){\n    ctx.fillStyle=\"rgba(5,10,5,.3)\";ctx.fillRect(0,0,140,46);\n    ctx.fillStyle=\"#0f0\";ctx.font=\"8px monospace\";\n    for(var i=0;i<cols;i++){\n      ctx.fillText(Math.random()>0.5?\"1\":\"0\",i*8,drops[i]*8);\n      if(drops[i]*8>46&&Math.random()>.95)drops[i]=0;drops[i]++;\n    }\n  },80);\n  b.addEventListener(\"mouseenter\",function(){b.style.boxShadow=\"0 0 20px rgba(0,255,0,.4)\";b.style.color=\"#fff\";});\n  b.addEventListener(\"mouseleave\",function(){b.style.boxShadow=\"none\";b.style.color=\"#0f0\";});\n})();<\\/script>","binaryRainBtn");

