add("Buttons","Particle Burst","\n<div style=\"display:flex;justify-content:center;align-items:center;height:90px;position:relative;\">\n<button id=\"XPBR\" style=\"padding:12px 28px;background:linear-gradient(135deg,#ff2d78,#ff6600);border:none;border-radius:10px;color:#fff;font-family:monospace;font-size:13px;font-weight:700;cursor:pointer;letter-spacing:1px;z-index:1;position:relative;\">&#127775; BURST</button>\n</div>\n<script>(function(){\n  var b=document.getElementById(\"XPBR\");if(!b)return;\n  b.addEventListener(\"click\",function(e){\n    var r=b.getBoundingClientRect(),wrap=b.parentElement;\n    for(var i=0;i<20;i++){\n      (function(i){\n        var p=document.createElement(\"div\"),a=Math.random()*360,d=30+Math.random()*70,sz=3+Math.random()*5;\n        var cols=[\"#ff2d78\",\"#ff6600\",\"#ffcc00\",\"#ff9900\",\"#fff\"];\n        p.style.cssText=\"position:absolute;width:\"+sz+\"px;height:\"+sz+\"px;border-radius:50%;background:\"+cols[i%5]+\";left:50%;top:50%;pointer-events:none;z-index:10;transition:all .8s cubic-bezier(.25,.46,.45,.94);\";\n        wrap.appendChild(p);\n        setTimeout(function(){\n          p.style.transform=\"translate(calc(\"+Math.cos(a*Math.PI/180)*d+\"px - 50%),calc(\"+Math.sin(a*Math.PI/180)*d+\"px - 50%))\";\n          p.style.opacity=\"0\";p.style.width=\"1px\";p.style.height=\"1px\";\n        },10);\n        setTimeout(function(){p.remove();},900);\n      })(i);\n    }\n  });\n})();<\\/script>","particleBurst");

