add("Buttons","Typewrite Click","\n<div style=\"display:flex;justify-content:center;padding:12px;\">\n<button id=\"XTWC\" style=\"padding:12px 20px;background:rgba(0,0,0,.4);border:1px solid rgba(123,92,255,.35);color:#7b5cff;font-family:monospace;font-size:13px;font-weight:700;cursor:pointer;letter-spacing:1px;min-width:160px;transition:border-color .2s;\">click me</button>\n</div>\n<script>(function(){\n  var b=document.getElementById(\"XTWC\");if(!b)return;\n  var phrases=[\"executing...\",\"sudo run magic\",\"npm run wow\",\"git push origin\"],pi=0;\n  b.addEventListener(\"click\",function(){\n    var txt=phrases[pi%phrases.length];pi++;b.textContent=\"\";var i=0;\n    b.style.borderColor=\"rgba(0,245,212,.6)\";\n    var iv=setInterval(function(){b.textContent+=txt[i++];if(i>=txt.length){clearInterval(iv);setTimeout(function(){b.textContent=\"click me\";b.style.borderColor=\"rgba(123,92,255,.35)\";},1200);}},60);\n  });\n})();<\\/script>","typewriteClick");

