add("Buttons","Tesla Coil","\n<div style=\"display:flex;justify-content:center;align-items:center;height:90px;position:relative;\">\n<canvas id=\"XTSC\" width=\"200\" height=\"90\" style=\"position:absolute;inset:0;width:200px;height:90px;pointer-events:none;\"></canvas>\n<button id=\"XTCB\" style=\"padding:12px 28px;background:linear-gradient(135deg,#0d1120,#1a1a2e);border:2px solid #7b5cff;color:#7b5cff;font-family:monospace;font-size:13px;font-weight:700;cursor:pointer;letter-spacing:1px;border-radius:8px;transition:all .2s;position:relative;z-index:1;\">&#9889; TESLA</button>\n</div>\n<script>(function(){\n  var cv=document.getElementById(\"XTSC\"),b=document.getElementById(\"XTCB\");if(!cv||!b)return;\n  var ctx=cv.getContext(\"2d\"),active=false;\n  function bolt(x1,y1,x2,y2,rough,depth){\n    if(depth<=0){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();return;}\n    var mx=(x1+x2)/2+(Math.random()-.5)*rough,my=(y1+y2)/2+(Math.random()-.5)*rough;\n    bolt(x1,y1,mx,my,rough*.5,depth-1);bolt(mx,my,x2,y2,rough*.5,depth-1);\n  }\n  function arc(){\n    if(!active)return;ctx.clearRect(0,0,200,90);\n    ctx.strokeStyle=\"rgba(123,92,255,.8)\";ctx.lineWidth=1.5;ctx.shadowBlur=8;ctx.shadowColor=\"#7b5cff\";\n    bolt(20,45,90,45,25,4);bolt(110,45,180,45,25,4);\n    ctx.shadowBlur=0;requestAnimationFrame(arc);\n  }\n  b.addEventListener(\"mouseenter\",function(){active=true;b.style.boxShadow=\"0 0 20px rgba(123,92,255,.5)\";b.style.color=\"#fff\";arc();});\n  b.addEventListener(\"mouseleave\",function(){active=false;ctx.clearRect(0,0,200,90);b.style.boxShadow=\"none\";b.style.color=\"#7b5cff\";});\n})();<\\/script>","teslaCoil");

