add("Cards","Terminal Card","\n<div style=\"background:#0a0a0a;border:1px solid #333;border-radius:8px;width:200px;overflow:hidden;font-family:monospace;\">\n  <div style=\"background:#1a1a1a;padding:6px 10px;display:flex;gap:5px;align-items:center;border-bottom:1px solid #333;\">\n    <div style=\"width:8px;height:8px;border-radius:50%;background:#ff5f57;\"></div>\n    <div style=\"width:8px;height:8px;border-radius:50%;background:#febc2e;\"></div>\n    <div style=\"width:8px;height:8px;border-radius:50%;background:#28c840;\"></div>\n    <span style=\"font-size:9px;color:#666;margin-left:6px;\">~/anime-cutbar</span>\n  </div>\n  <div style=\"padding:10px;font-size:10px;line-height:1.8;\">\n    <div><span style=\"color:#28c840;\">&#10095;</span> <span style=\"color:#00f5d4;\">git</span> <span style=\"color:#fff;\">push origin main</span></div>\n    <div style=\"color:#888;\">Enumerating objects: 5</div>\n    <div style=\"color:#888;\">Writing objects: 100%</div>\n    <div><span style=\"color:#28c840;\">&#10003;</span> <span style=\"color:#28c840;\">Deployed!</span></div>\n    <div style=\"margin-top:4px;\"><span style=\"color:#28c840;\">&#10095;</span> <span id=\"XTCD\" style=\"color:#fff;border-right:2px solid #0f0;animation:tblink .8s infinite;padding-right:2px;\"></span></div>\n  </div>\n</div>\n<script>(function(){\n  var el=document.getElementById(\"XTCD\");if(!el)return;\n  var cmds=[\"npm run build\",\"ls -la\",\"cat package.json\"],ci=0,chi=0;\n  function type(){if(chi<cmds[ci].length){el.textContent+=cmds[ci][chi++];setTimeout(type,80);}else{setTimeout(function(){el.textContent=\"\";chi=0;ci=(ci+1)%cmds.length;setTimeout(type,400);},1500);}}\n  type();\n})();<\\/script>","terminalCard");

add("Cards","Notification Card","\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:4px;width:210px;\" id=\"XNTW\">\n  <style>@keyframes slideIn{from{transform:translateX(20px);opacity:0}to{transform:translateX(0);opacity:1}}</style>\n  <div style=\"background:rgba(0,204,85,.08);border:1px solid rgba(0,204,85,.2);border-radius:10px;padding:10px 12px;display:flex;gap:8px;align-items:flex-start;animation:slideIn .3s ease-out;\">\n    <div style=\"font-size:16px;flex-shrink:0;margin-top:1px;\">&#9989;</div>\n    <div><div style=\"font-size:11px;color:#fff;font-family:monospace;font-weight:700;\">Deployed!</div><div style=\"font-size:9px;color:#4a5580;font-family:monospace;margin-top:2px;\">Build completed in 1.2s</div></div>\n  </div>\n  <div style=\"background:rgba(255,204,0,.08);border:1px solid rgba(255,204,0,.2);border-radius:10px;padding:10px 12px;display:flex;gap:8px;align-items:flex-start;animation:slideIn .3s ease-out .1s both;\">\n    <div style=\"font-size:16px;flex-shrink:0;margin-top:1px;\">&#9888;&#65039;</div>\n    <div><div style=\"font-size:11px;color:#fff;font-family:monospace;font-weight:700;\">Rate Limit</div><div style=\"font-size:9px;color:#4a5580;font-family:monospace;margin-top:2px;\">API at 80% capacity</div></div>\n  </div>\n  <div style=\"background:rgba(255,45,120,.08);border:1px solid rgba(255,45,120,.2);border-radius:10px;padding:10px 12px;display:flex;gap:8px;align-items:flex-start;animation:slideIn .3s ease-out .2s both;\">\n    <div style=\"font-size:16px;flex-shrink:0;margin-top:1px;\">&#128683;</div>\n    <div><div style=\"font-size:11px;color:#fff;font-family:monospace;font-weight:700;\">Auth Failed</div><div style=\"font-size:9px;color:#4a5580;font-family:monospace;margin-top:2px;\">Invalid token detected</div></div>\n  </div>\n</div>","notifCard");

add("Cards","Task Board","\n<div style=\"background:rgba(13,17,32,.95);border:1px solid rgba(123,92,255,.15);border-radius:14px;padding:14px;width:200px;font-family:monospace;\">\n  <div style=\"font-size:9px;letter-spacing:2px;color:#4a5580;margin-bottom:10px;\">SPRINT BOARD</div>\n  <div style=\"display:flex;flex-direction:column;gap:6px;\">\n    <div style=\"padding:8px 10px;background:rgba(0,204,85,.06);border-left:3px solid #00cc55;border-radius:0 6px 6px 0;\">\n      <div style=\"font-size:10px;color:#dde4f8;\">Design system</div>\n      <div style=\"font-size:8px;color:#00cc55;margin-top:2px;\">DONE</div>\n    </div>\n    <div style=\"padding:8px 10px;background:rgba(255,204,0,.06);border-left:3px solid #ffcc00;border-radius:0 6px 6px 0;\">\n      <div style=\"font-size:10px;color:#dde4f8;\">Add 50 components</div>\n      <div style=\"font-size:8px;color:#ffcc00;margin-top:2px;\">IN PROGRESS</div>\n    </div>\n    <div style=\"padding:8px 10px;background:rgba(123,92,255,.06);border-left:3px solid #7b5cff;border-radius:0 6px 6px 0;\">\n      <div style=\"font-size:10px;color:#dde4f8;\">AdSense monetize</div>\n      <div style=\"font-size:8px;color:#7b5cff;margin-top:2px;\">TODO</div>\n    </div>\n    <div style=\"padding:8px 10px;background:rgba(255,45,120,.06);border-left:3px solid #ff2d78;border-radius:0 6px 6px 0;\">\n      <div style=\"font-size:10px;color:#dde4f8;\">Ship to production</div>\n      <div style=\"font-size:8px;color:#ff2d78;margin-top:2px;\">BLOCKED</div>\n    </div>\n  </div>\n</div>","taskBoard");

add("Science","Conway Life","\n<canvas id=\"XCGL\" width=\"180\" height=\"120\" style=\"width:180px;height:120px;border-radius:8px;cursor:pointer;\" title=\"click to reset\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XCGL\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),W=180,H=120,sz=6,cols=Math.floor(W/sz),rows=Math.floor(H/sz);\n  function makeGrid(){var g=[];for(var i=0;i<rows;i++){g[i]=[];for(var j=0;j<cols;j++)g[i][j]=Math.random()>.72?1:0;}return g;}\n  var grid=makeGrid();\n  function neighbors(g,r,c2){var n=0;for(var dr=-1;dr<=1;dr++)for(var dc=-1;dc<=1;dc++){if(dr===0&&dc===0)continue;var nr=(r+dr+rows)%rows,nc=(c2+dc+cols)%cols;n+=g[nr][nc];}return n;}\n  function step(){var ng=[];for(var r=0;r<rows;r++){ng[r]=[];for(var c2=0;c2<cols;c2++){var n=neighbors(grid,r,c2);ng[r][c2]=grid[r][c2]?n===2||n===3?1:0:n===3?1:0;}}grid=ng;}\n  function draw(){\n    ctx.fillStyle=\"#07090f\";ctx.fillRect(0,0,W,H);\n    for(var r=0;r<rows;r++)for(var c2=0;c2<cols;c2++)if(grid[r][c2]){\n      var n=neighbors(grid,r,c2)/8;\n      ctx.fillStyle=\"rgba(\"+(Math.round(0+123*n))+\",\"+(Math.round(245-153*n))+\",\"+(Math.round(212-12*n))+\",0.9)\";\n      ctx.fillRect(c2*sz+1,r*sz+1,sz-1,sz-1);\n    }\n  }\n  c.addEventListener(\"click\",function(){grid=makeGrid();});\n  setInterval(function(){step();draw();},120);draw();\n})();<\\/script>","conwayLife");

add("Science","Turing Pattern","\n<canvas id=\"XTUR\" width=\"160\" height=\"120\" style=\"width:160px;height:120px;border-radius:8px;cursor:pointer;\" title=\"click to regenerate\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XTUR\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),W=160,H=120,sz=4,cols=Math.floor(W/sz),rows=Math.floor(H/sz);\n  function run(){\n    var A=[],B=[],nA=[],nB=[];\n    for(var i=0;i<rows;i++){A[i]=[];B[i]=[];nA[i]=[];nB[i]=[];for(var j=0;j<cols;j++){A[i][j]=Math.random();B[i][j]=Math.random();}}\n    var dA=1,dB=.5,f=.055,k=.062;\n    for(var step=0;step<80;step++){\n      for(var r=0;r<rows;r++){for(var c2=0;c2<cols;c2++){\n        var t=(r-1+rows)%rows,b=(r+1)%rows,l=(c2-1+cols)%cols,ri=(c2+1)%cols;\n        var lA=A[t][c2]+A[b][c2]+A[r][l]+A[r][ri]-4*A[r][c2];\n        var lB=B[t][c2]+B[b][c2]+B[r][l]+B[r][ri]-4*B[r][c2];\n        var a=A[r][c2],b2=B[r][c2],ab=a*b2*b2;\n        nA[r][c2]=Math.max(0,Math.min(1,a+dA*lA-ab+f*(1-a)));\n        nB[r][c2]=Math.max(0,Math.min(1,b2+dB*lB+ab-(k+f)*b2));\n      }}\n      for(var r=0;r<rows;r++)for(var c2=0;c2<cols;c2++){A[r][c2]=nA[r][c2];B[r][c2]=nB[r][c2];}\n    }\n    var img=ctx.createImageData(W,H);\n    for(var r=0;r<rows;r++)for(var c2=0;c2<cols;c2++){\n      var v=A[r][c2],idx=(r*sz*W+c2*sz)*4;\n      for(var dy=0;dy<sz;dy++)for(var dx=0;dx<sz;dx++){\n        var i2=((r*sz+dy)*W+(c2*sz+dx))*4;\n        img.data[i2]=Math.round(v*123);img.data[i2+1]=Math.round(v*92);img.data[i2+2]=Math.round(v*255);img.data[i2+3]=255;\n      }\n    }\n    ctx.putImageData(img,0,0);\n  }\n  run();c.addEventListener(\"click\",run);\n})();<\\/script>","turingPattern");

add("Science","Fourier Sound","\n<canvas id=\"XFSD\" width=\"180\" height=\"100\" style=\"width:180px;height:100px;\"></canvas>\n<div style=\"display:flex;justify-content:center;gap:8px;margin-top:6px;\">\n  <button onclick=\"window.XFSD_freq=220\" style=\"padding:3px 8px;border:1px solid rgba(0,245,212,.3);background:transparent;color:#00f5d4;font-family:monospace;font-size:9px;cursor:pointer;border-radius:4px;\">220Hz</button>\n  <button onclick=\"window.XFSD_freq=440\" style=\"padding:3px 8px;border:1px solid rgba(123,92,255,.3);background:transparent;color:#7b5cff;font-family:monospace;font-size:9px;cursor:pointer;border-radius:4px;\">440Hz</button>\n  <button onclick=\"window.XFSD_freq=880\" style=\"padding:3px 8px;border:1px solid rgba(255,45,120,.3);background:transparent;color:#ff2d78;font-family:monospace;font-size:9px;cursor:pointer;border-radius:4px;\">880Hz</button>\n</div>\n<script>(function(){\n  var c=document.getElementById(\"XFSD\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),t=0;\n  window.XFSD_freq=440;\n  function draw(){\n    ctx.clearRect(0,0,180,100);\n    ctx.beginPath();\n    var grad=ctx.createLinearGradient(0,0,180,0);\n    grad.addColorStop(0,\"#00f5d4\");grad.addColorStop(.5,\"#7b5cff\");grad.addColorStop(1,\"#ff2d78\");\n    ctx.strokeStyle=grad;ctx.lineWidth=2.5;ctx.shadowBlur=8;ctx.shadowColor=\"#7b5cff\";\n    for(var x=0;x<180;x++){\n      var phase=x/180*Math.PI*2*(window.XFSD_freq/440);\n      var y=50+Math.sin(phase+t)*28+Math.sin(phase*2+t*1.3)*10+Math.sin(phase*3+t*.7)*5;\n      if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);\n    }\n    ctx.stroke();ctx.shadowBlur=0;t+=.06;requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","fourierSound");

add("Science","Mandelbrot Zoom","\n<canvas id=\"XMBZ\" width=\"160\" height=\"120\" style=\"width:160px;height:120px;border-radius:8px;cursor:pointer;\" title=\"click to zoom in\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XMBZ\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),W=160,H=120;\n  var cx=-0.7,cy=0,zoom=1.5,maxIter=64;\n  function draw(){\n    var img=ctx.createImageData(W,H);\n    for(var px=0;px<W;px++){for(var py=0;py<H;py++){\n      var x0=(px/W-0.5)*zoom+cx,y0=(py/H-0.5)*zoom*(H/W)+cy;\n      var x=0,y=0,it=0;\n      while(x*x+y*y<4&&it<maxIter){var xt=x*x-y*y+x0;y=2*x*y+y0;x=xt;it++;}\n      var i=(py*W+px)*4;\n      if(it===maxIter){img.data[i]=7;img.data[i+1]=9;img.data[i+2]=15;img.data[i+3]=255;}\n      else{var t=it/maxIter;img.data[i]=Math.round(123*t);img.data[i+1]=Math.round(92*t);img.data[i+2]=Math.round(255*Math.sqrt(t));img.data[i+3]=255;}\n    }}\n    ctx.putImageData(img,0,0);\n  }\n  c.addEventListener(\"click\",function(e){var r=c.getBoundingClientRect();var mx=(e.clientX-r.left)/W,my=(e.clientY-r.top)/H;cx+=(mx-0.5)*zoom;cy+=(my-0.5)*zoom*(H/W);zoom*=.5;draw();});\n  draw();\n})();<\\/script>","mandelbrotZoom");

add("Science","Particle Attractor","\n<canvas id=\"XPAT\" width=\"180\" height=\"120\" style=\"width:180px;height:120px;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XPAT\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),W=180,H=120,mx=W/2,my=H/2;\n  var particles=[];\n  for(var i=0;i<60;i++)particles.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*2,vy:(Math.random()-.5)*2,col:[\"#00f5d4\",\"#7b5cff\",\"#ff2d78\"][Math.floor(Math.random()*3)]});\n  c.addEventListener(\"mousemove\",function(e){var r=c.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top;});\n  function tick(){\n    ctx.fillStyle=\"rgba(7,9,15,.18)\";ctx.fillRect(0,0,W,H);\n    particles.forEach(function(p){\n      var dx=mx-p.x,dy=my-p.y,d=Math.sqrt(dx*dx+dy*dy)+1;\n      p.vx+=dx/d*0.5;p.vy+=dy/d*0.5;p.vx*=.95;p.vy*=.95;\n      p.x+=p.vx;p.y+=p.vy;\n      if(p.x<0)p.x=W;if(p.x>W)p.x=0;if(p.y<0)p.y=H;if(p.y>H)p.y=0;\n      ctx.beginPath();ctx.arc(p.x,p.y,2,0,6.28);ctx.fillStyle=p.col;ctx.shadowBlur=6;ctx.shadowColor=p.col;ctx.fill();ctx.shadowBlur=0;\n    });\n    requestAnimationFrame(tick);\n  }\n  tick();\n})();<\\/script>","particleAttractor");

add("Gaming","Skill Tree","\n<div style=\"padding:10px;display:flex;flex-direction:column;align-items:center;gap:6px;\">\n  <style>\n    .stn{width:44px;height:44px;border-radius:10px;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:all .25s;font-size:18px;}\n    .stn.locked{background:rgba(255,255,255,.04);border:2px solid rgba(255,255,255,.08);filter:grayscale(1);opacity:.4;cursor:not-allowed;}\n    .stn.unlocked{background:rgba(123,92,255,.15);border:2px solid rgba(123,92,255,.4);box-shadow:0 0 14px rgba(123,92,255,.25);}\n    .stn.active{background:linear-gradient(135deg,rgba(123,92,255,.3),rgba(0,245,212,.2));border:2px solid #00f5d4;box-shadow:0 0 20px rgba(0,245,212,.4);}\n    .conn{width:2px;height:16px;background:rgba(255,255,255,.1);border-radius:1px;}\n    .conn.lit{background:linear-gradient(to bottom,#7b5cff,#00f5d4);box-shadow:0 0 6px rgba(123,92,255,.4);}\n  </style>\n  <div class=\"stn active\">&#9889;</div>\n  <div class=\"conn lit\"></div>\n  <div style=\"display:flex;gap:20px;\">\n    <div style=\"display:flex;flex-direction:column;align-items:center;gap:6px;\">\n      <div class=\"stn unlocked\" onclick=\"this.classList.toggle('active');this.classList.toggle('unlocked')\">&#128293;</div>\n      <div class=\"conn\"></div>\n      <div class=\"stn locked\">&#128165;</div>\n    </div>\n    <div style=\"display:flex;flex-direction:column;align-items:center;gap:6px;\">\n      <div class=\"stn unlocked\" onclick=\"this.classList.toggle('active');this.classList.toggle('unlocked')\">&#128737;</div>\n      <div class=\"conn\"></div>\n      <div class=\"stn locked\">&#9876;&#65039;</div>\n    </div>\n  </div>\n</div>","skillTree");

add("Gaming","XP Bar","\n<div style=\"padding:14px;width:220px;\">\n  <div style=\"display:flex;justify-content:space-between;margin-bottom:5px;\">\n    <span style=\"font-family:monospace;font-size:10px;color:#7b5cff;letter-spacing:1px;\">&#9876;&#65039; LVL 7</span>\n    <span id=\"XXPV\" style=\"font-family:monospace;font-size:10px;color:#7b5cff;\">3,240 XP</span>\n  </div>\n  <div style=\"height:10px;background:rgba(123,92,255,.1);border-radius:5px;overflow:hidden;border:1px solid rgba(123,92,255,.2);\">\n    <div id=\"XXPB\" style=\"height:100%;width:54%;background:linear-gradient(90deg,#7b5cff,#00f5d4);border-radius:5px;transition:width .6s cubic-bezier(.34,1.56,.64,1);box-shadow:0 0 10px rgba(123,92,255,.5);\"></div>\n  </div>\n  <div style=\"font-family:monospace;font-size:8px;color:#4a5580;margin-top:4px;text-align:right;\">6,000 to next level</div>\n  <button onclick=\"(function(){var b=document.getElementById('XXPB'),xp=document.getElementById('XXPV');var p=parseFloat(b.style.width)||54;p=Math.min(100,p+Math.random()*18+5);b.style.width=p+'%';xp.textContent=Math.round(p*60)+' XP';})()\" style=\"margin-top:10px;width:100%;padding:6px;border:1px solid rgba(123,92,255,.3);background:transparent;color:#7b5cff;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;letter-spacing:1px;\">+ GAIN XP</button>\n</div>","xpBar");

add("Gaming","Lives Counter","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:12px;padding:14px;\">\n  <div id=\"XLVC\" style=\"display:flex;gap:6px;\">\n    <div style=\"font-size:26px;transition:all .3s;filter:drop-shadow(0 0 6px rgba(255,45,120,.7));\">&#10084;&#65039;</div>\n    <div style=\"font-size:26px;transition:all .3s;filter:drop-shadow(0 0 6px rgba(255,45,120,.7));\">&#10084;&#65039;</div>\n    <div style=\"font-size:26px;transition:all .3s;filter:drop-shadow(0 0 6px rgba(255,45,120,.7));\">&#10084;&#65039;</div>\n  </div>\n  <div style=\"display:flex;gap:8px;\">\n    <button onclick=\"(function(){var l=document.getElementById('XLVC'),h=[].slice.call(l.children),a=h.filter(function(x){return x.style.opacity!=='0';});if(a.length){var h2=a[a.length-1];h2.style.transform='scale(0)';h2.style.opacity='0';}})()\" style=\"padding:5px 12px;border:1px solid rgba(255,45,120,.3);background:transparent;color:#ff2d78;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">- LIFE</button>\n    <button onclick=\"(function(){var l=document.getElementById('XLVC'),h=[].slice.call(l.children),d=h.filter(function(x){return x.style.opacity==='0';});if(d.length){var h2=d[0];h2.innerHTML='&#10084;&#65039;';h2.style.opacity='1';h2.style.transform='scale(1.3)';setTimeout(function(){h2.style.transform='scale(1)';},200);}})()\" style=\"padding:5px 12px;border:1px solid rgba(0,245,212,.3);background:transparent;color:#00f5d4;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">+ LIFE</button>\n  </div>\n</div>","livesCounter");

add("Gaming","Inventory","\n<div style=\"padding:10px;\">\n  <div style=\"display:grid;grid-template-columns:repeat(4,44px);gap:6px;\">\n    <style>\n      .inv{width:44px;height:44px;border-radius:8px;background:rgba(0,0,0,.3);border:2px solid rgba(255,255,255,.07);display:flex;align-items:center;justify-content:center;font-size:20px;cursor:pointer;transition:all .2s;position:relative;}\n      .inv:hover{border-color:rgba(123,92,255,.5);box-shadow:0 0 10px rgba(123,92,255,.2);}\n      .inv.sel{border-color:#00f5d4;box-shadow:0 0 14px rgba(0,245,212,.3);background:rgba(0,245,212,.04);}\n      .qty{position:absolute;bottom:2px;right:4px;font-family:monospace;font-size:8px;color:#ffaa00;font-weight:700;}\n    </style>\n    <div class=\"inv\" onclick=\"[...document.querySelectorAll('.inv')].forEach(function(i){i.classList.remove('sel')});this.classList.add('sel')\">&#9876;&#65039;<span class=\"qty\">1</span></div>\n    <div class=\"inv\" onclick=\"[...document.querySelectorAll('.inv')].forEach(function(i){i.classList.remove('sel')});this.classList.add('sel')\">&#128737;&#65039;<span class=\"qty\">1</span></div>\n    <div class=\"inv\" onclick=\"[...document.querySelectorAll('.inv')].forEach(function(i){i.classList.remove('sel')});this.classList.add('sel')\">&#129514;<span class=\"qty\">5</span></div>\n    <div class=\"inv\" onclick=\"[...document.querySelectorAll('.inv')].forEach(function(i){i.classList.remove('sel')});this.classList.add('sel')\">&#128142;<span class=\"qty\">12</span></div>\n    <div class=\"inv\" onclick=\"[...document.querySelectorAll('.inv')].forEach(function(i){i.classList.remove('sel')});this.classList.add('sel')\">&#128273;<span class=\"qty\">3</span></div>\n    <div class=\"inv\" onclick=\"[...document.querySelectorAll('.inv')].forEach(function(i){i.classList.remove('sel')});this.classList.add('sel')\">&#127993;<span class=\"qty\">8</span></div>\n    <div class=\"inv\"></div>\n    <div class=\"inv\"></div>\n  </div>\n</div>","inventory");

add("Gaming","Achievement Badge","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px;\">\n  <style>@keyframes badgeSpin{to{transform:rotate(360deg)}}</style>\n  <div style=\"width:80px;height:80px;border-radius:50%;background:linear-gradient(135deg,#1a1a2e,#0d1120);border:3px solid rgba(255,204,0,.3);display:flex;align-items:center;justify-content:center;font-size:32px;position:relative;overflow:hidden;\">\n    &#127942;\n    <div style=\"position:absolute;inset:0;background:conic-gradient(transparent 0deg,rgba(255,204,0,.2) 90deg,transparent 180deg);border-radius:50%;animation:badgeSpin 3s linear infinite;pointer-events:none;\"></div>\n  </div>\n  <div style=\"text-align:center;\">\n    <div style=\"font-family:monospace;font-size:11px;font-weight:700;color:#ffcc00;letter-spacing:1px;\">MASTER BUILDER</div>\n    <div style=\"font-family:monospace;font-size:9px;color:#4a5580;margin-top:2px;\">Built 150 components</div>\n  </div>\n</div>","achievementBadge");

add("Inputs","Search Bar","\n<div style=\"padding:10px;width:220px;\">\n<div id=\"XSRW\" style=\"display:flex;align-items:center;gap:10px;padding:10px 14px;background:rgba(0,0,0,.35);border:1px solid rgba(123,92,255,.2);border-radius:100px;cursor:text;transition:all .3s;\">\n  <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4a5580\" stroke-width=\"2.5\" id=\"XSRi\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n  <input id=\"XSRI\" type=\"text\" placeholder=\"Search components...\" style=\"border:none;background:transparent;color:#dde4f8;font-family:monospace;font-size:11px;outline:none;width:100%;caret-color:#7b5cff;\" onclick=\"this.focus()\">\n</div>\n</div>\n<script>(function(){\n  var inp=document.getElementById(\"XSRI\"),wrap=document.getElementById(\"XSRW\"),icon=document.getElementById(\"XSRi\");if(!inp)return;\n  inp.addEventListener(\"focus\",function(){wrap.style.borderColor=\"rgba(123,92,255,.6)\";wrap.style.boxShadow=\"0 0 20px rgba(123,92,255,.15)\";icon.setAttribute(\"stroke\",\"#7b5cff\");});\n  inp.addEventListener(\"blur\",function(){wrap.style.borderColor=\"rgba(123,92,255,.2)\";wrap.style.boxShadow=\"none\";icon.setAttribute(\"stroke\",\"#4a5580\");});\n})();<\\/script>","searchBar");

add("Inputs","Glow Checkbox","\n<div style=\"display:flex;flex-direction:column;gap:10px;padding:10px;\">\n  <style>\n    .gcw{display:flex;align-items:center;gap:10px;cursor:pointer;}\n    .gcw input{display:none;}\n    .gcw .gb2{width:20px;height:20px;border-radius:5px;border:2px solid rgba(123,92,255,.4);background:transparent;transition:all .25s;display:flex;align-items:center;justify-content:center;flex-shrink:0;}\n    .gcw input:checked~.gb2{background:linear-gradient(135deg,#7b5cff,#00f5d4);border-color:transparent;box-shadow:0 0 12px rgba(123,92,255,.5);}\n    .gcw .gl2{font-family:monospace;font-size:11px;color:#7b8ab8;transition:color .25s;}\n    .gcw input:checked~.gl2{color:#dde4f8;}\n  </style>\n  <label class=\"gcw\"><input type=\"checkbox\" checked><div class=\"gb2\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"2,6 5,9 10,3\"/></svg></div><span class=\"gl2\">Animations enabled</span></label>\n  <label class=\"gcw\"><input type=\"checkbox\" checked><div class=\"gb2\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"2,6 5,9 10,3\"/></svg></div><span class=\"gl2\">Dark mode</span></label>\n  <label class=\"gcw\"><input type=\"checkbox\"><div class=\"gb2\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"2,6 5,9 10,3\"/></svg></div><span class=\"gl2\">Auto copy</span></label>\n  <label class=\"gcw\"><input type=\"checkbox\"><div class=\"gb2\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"2,6 5,9 10,3\"/></svg></div><span class=\"gl2\">Show previews</span></label>\n</div>","glowCheckbox");

add("Inputs","Color Swatches","\n<div style=\"padding:10px;display:flex;flex-direction:column;gap:10px;align-items:center;\">\n  <div id=\"XCSP\" style=\"width:80px;height:80px;border-radius:16px;background:#7b5cff;box-shadow:0 0 24px rgba(123,92,255,.5);transition:all .3s;border:3px solid rgba(255,255,255,.1);\"></div>\n  <div style=\"display:flex;gap:8px;flex-wrap:wrap;justify-content:center;max-width:180px;\">\n    <div onclick=\"document.getElementById('XCSP').style.background='#00f5d4';document.getElementById('XCSP').style.boxShadow='0 0 24px rgba(0,245,212,.5)'\" style=\"width:22px;height:22px;border-radius:6px;background:#00f5d4;cursor:pointer;transition:transform .2s;\" onmouseover=\"this.style.transform='scale(1.2)'\" onmouseout=\"this.style.transform='scale(1)'\"></div>\n    <div onclick=\"document.getElementById('XCSP').style.background='#7b5cff';document.getElementById('XCSP').style.boxShadow='0 0 24px rgba(123,92,255,.5)'\" style=\"width:22px;height:22px;border-radius:6px;background:#7b5cff;cursor:pointer;transition:transform .2s;\" onmouseover=\"this.style.transform='scale(1.2)'\" onmouseout=\"this.style.transform='scale(1)'\"></div>\n    <div onclick=\"document.getElementById('XCSP').style.background='#ff2d78';document.getElementById('XCSP').style.boxShadow='0 0 24px rgba(255,45,120,.5)'\" style=\"width:22px;height:22px;border-radius:6px;background:#ff2d78;cursor:pointer;transition:transform .2s;\" onmouseover=\"this.style.transform='scale(1.2)'\" onmouseout=\"this.style.transform='scale(1)'\"></div>\n    <div onclick=\"document.getElementById('XCSP').style.background='#ffaa00';document.getElementById('XCSP').style.boxShadow='0 0 24px rgba(255,170,0,.5)'\" style=\"width:22px;height:22px;border-radius:6px;background:#ffaa00;cursor:pointer;transition:transform .2s;\" onmouseover=\"this.style.transform='scale(1.2)'\" onmouseout=\"this.style.transform='scale(1)'\"></div>\n    <div onclick=\"document.getElementById('XCSP').style.background='#00cc55';document.getElementById('XCSP').style.boxShadow='0 0 24px rgba(0,204,85,.5)'\" style=\"width:22px;height:22px;border-radius:6px;background:#00cc55;cursor:pointer;transition:transform .2s;\" onmouseover=\"this.style.transform='scale(1.2)'\" onmouseout=\"this.style.transform='scale(1)'\"></div>\n    <div onclick=\"document.getElementById('XCSP').style.background='#ff6600';document.getElementById('XCSP').style.boxShadow='0 0 24px rgba(255,102,0,.5)'\" style=\"width:22px;height:22px;border-radius:6px;background:#ff6600;cursor:pointer;transition:transform .2s;\" onmouseover=\"this.style.transform='scale(1.2)'\" onmouseout=\"this.style.transform='scale(1)'\"></div>\n  </div>\n</div>","colorSwatches");

add("Inputs","Tag Input","\n<div style=\"padding:10px;width:220px;\">\n  <div id=\"XTIG\" style=\"display:flex;flex-wrap:wrap;gap:5px;padding:8px;background:rgba(0,0,0,.35);border:1px solid rgba(123,92,255,.25);border-radius:10px;min-height:42px;cursor:text;\" onclick=\"document.getElementById('XTII').focus()\">\n    <style>.xtag{display:flex;align-items:center;gap:4px;padding:3px 8px;background:rgba(123,92,255,.2);border:1px solid rgba(123,92,255,.35);border-radius:6px;font-family:monospace;font-size:10px;color:#a090ff;}</style>\n    <div class=\"xtag\">UI <span onclick=\"this.parentElement.remove()\" style=\"cursor:pointer;color:#ff2d78;font-size:12px;line-height:1;\">x</span></div>\n    <div class=\"xtag\">CSS <span onclick=\"this.parentElement.remove()\" style=\"cursor:pointer;color:#ff2d78;font-size:12px;line-height:1;\">x</span></div>\n    <input id=\"XTII\" type=\"text\" placeholder=\"add tag...\" style=\"border:none;background:transparent;color:#dde4f8;font-family:monospace;font-size:11px;outline:none;min-width:60px;flex:1;caret-color:#7b5cff;\">\n  </div>\n</div>\n<script>(function(){\n  var inp=document.getElementById(\"XTII\"),tags=document.getElementById(\"XTIG\");if(!inp)return;\n  inp.addEventListener(\"keydown\",function(e){\n    if((e.key===\"Enter\"||e.key===\",\")&&inp.value.trim()){\n      e.preventDefault();var v=inp.value.trim().replace(\",\",\"\");\n      var tag=document.createElement(\"div\");tag.className=\"xtag\";\n      tag.innerHTML=v+\" <span onclick=\"this.parentElement.remove()\" style=\"cursor:pointer;color:#ff2d78;font-size:12px;line-height:1;\">x</span>\";\n      tags.insertBefore(tag,inp);inp.value=\"\";\n    }else if(e.key===\"Backspace\"&&!inp.value){var tgs=[].slice.call(tags.querySelectorAll(\".xtag\"));if(tgs.length)tgs[tgs.length-1].remove();}\n  });\n})();<\\/script>","tagInput");

add("Clocks","Countdown Timer","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:12px;padding:14px;\">\n  <div style=\"display:flex;gap:12px;align-items:flex-start;\">\n    <div style=\"text-align:center;\">\n      <div id=\"XCDD\" style=\"font-family:'Orbitron',monospace,sans-serif;font-size:32px;font-weight:700;color:#7b5cff;text-shadow:0 0 16px rgba(123,92,255,.5);width:72px;text-align:center;\">02</div>\n      <div style=\"font-family:monospace;font-size:8px;color:#4a5580;letter-spacing:2px;\">MIN</div>\n    </div>\n    <div style=\"font-family:monospace;font-size:28px;color:#7b5cff;margin-top:5px;\">:</div>\n    <div style=\"text-align:center;\">\n      <div id=\"XCDS\" style=\"font-family:'Orbitron',monospace,sans-serif;font-size:32px;font-weight:700;color:#7b5cff;text-shadow:0 0 16px rgba(123,92,255,.5);width:72px;text-align:center;\">00</div>\n      <div style=\"font-family:monospace;font-size:8px;color:#4a5580;letter-spacing:2px;\">SEC</div>\n    </div>\n  </div>\n  <div style=\"display:flex;gap:8px;\">\n    <button id=\"XCDst\" onclick=\"(function(){if(window.XCDrun)return;window.XCDrun=true;var tot=window.XCDtot||120;window.XCDiv=setInterval(function(){if(tot<=0){clearInterval(window.XCDiv);window.XCDrun=false;document.getElementById('XCDD').textContent='00';document.getElementById('XCDS').textContent='00';return;}tot--;window.XCDtot=tot;document.getElementById('XCDD').textContent=String(Math.floor(tot/60)).padStart(2,'0');document.getElementById('XCDS').textContent=String(tot%60).padStart(2,'0');},1000);})()\" style=\"padding:6px 14px;border:1px solid rgba(0,245,212,.3);background:transparent;color:#00f5d4;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">START</button>\n    <button onclick=\"clearInterval(window.XCDiv);window.XCDrun=false;\" style=\"padding:6px 14px;border:1px solid rgba(255,45,120,.3);background:transparent;color:#ff2d78;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">STOP</button>\n    <button onclick=\"clearInterval(window.XCDiv);window.XCDrun=false;window.XCDtot=120;document.getElementById('XCDD').textContent='02';document.getElementById('XCDS').textContent='00';\" style=\"padding:6px 14px;border:1px solid rgba(255,255,255,.08);background:transparent;color:#4a5580;font-family:monospace;font-size:10px;cursor:pointer;border-radius:6px;\">RESET</button>\n  </div>\n</div>","countdownTimer");

add("Clocks","Flip Clock","\n<div style=\"display:flex;gap:4px;align-items:center;padding:10px;justify-content:center;\">\n  <style>\n    .fcd{width:36px;height:46px;background:linear-gradient(180deg,#1a1a2e 50%,#0d1120 50%);border-radius:6px;display:flex;align-items:center;justify-content:center;font-family:'Orbitron',monospace,sans-serif;font-size:22px;font-weight:700;color:#00f5d4;text-shadow:0 0 10px rgba(0,245,212,.5);border:1px solid rgba(0,245,212,.15);position:relative;}\n    .fcd::after{content:'';position:absolute;top:50%;left:0;right:0;height:1px;background:rgba(0,0,0,.5);}\n    .fcs{font-family:monospace;font-size:22px;color:#ff2d78;margin:0 2px;animation:fcblink .8s step-end infinite;}\n    @keyframes fcblink{0%,100%{opacity:1}50%{opacity:0}}\n  </style>\n  <div id=\"XFCh1\" class=\"fcd\">0</div><div id=\"XFCh2\" class=\"fcd\">0</div>\n  <div class=\"fcs\">:</div>\n  <div id=\"XFCm1\" class=\"fcd\">0</div><div id=\"XFCm2\" class=\"fcd\">0</div>\n  <div class=\"fcs\">:</div>\n  <div id=\"XFCs1\" class=\"fcd\" style=\"color:#ff2d78;text-shadow:0 0 10px rgba(255,45,120,.5);border-color:rgba(255,45,120,.15);\">0</div>\n  <div id=\"XFCs2\" class=\"fcd\" style=\"color:#ff2d78;text-shadow:0 0 10px rgba(255,45,120,.5);border-color:rgba(255,45,120,.15);\">0</div>\n</div>\n<script>(function(){\n  function u(id,v){var el=document.getElementById(id);if(el)el.textContent=v;}\n  function tick(){\n    var n=new Date(),h=String(n.getHours()).padStart(2,\"0\"),m=String(n.getMinutes()).padStart(2,\"0\"),s=String(n.getSeconds()).padStart(2,\"0\");\n    u(\"XFCh1\",h[0]);u(\"XFCh2\",h[1]);u(\"XFCm1\",m[0]);u(\"XFCm2\",m[1]);u(\"XFCs1\",s[0]);u(\"XFCs2\",s[1]);\n  }\n  setInterval(tick,500);tick();\n})();<\\/script>","flipClock");

add("Anime FX","Explosion Burst","\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:12px;padding:10px;\">\n<div style=\"position:relative;width:120px;height:100px;display:flex;align-items:center;justify-content:center;\">\n  <canvas id=\"XEXP\" width=\"120\" height=\"100\" style=\"position:absolute;inset:0;width:120px;height:100px;pointer-events:none;\"></canvas>\n  <button id=\"XEXPB\" style=\"padding:10px 20px;background:linear-gradient(135deg,#ff6600,#ff2d78);border:none;border-radius:10px;color:#fff;font-family:monospace;font-size:12px;font-weight:700;cursor:pointer;letter-spacing:1px;position:relative;z-index:1;\">&#128165; BOOM</button>\n</div>\n</div>\n<script>(function(){\n  var cv=document.getElementById(\"XEXP\"),b=document.getElementById(\"XEXPB\");if(!cv||!b)return;\n  var ctx=cv.getContext(\"2d\");\n  b.addEventListener(\"click\",function(){\n    var parts=[];\n    for(var i=0;i<30;i++){\n      var a=Math.random()*360,d=30+Math.random()*40;\n      parts.push({x:60,y:50,vx:Math.cos(a*Math.PI/180)*(2+Math.random()*4),vy:Math.sin(a*Math.PI/180)*(2+Math.random()*4),life:1,col:[\"#ff2d78\",\"#ff6600\",\"#ffcc00\",\"#00f5d4\",\"#7b5cff\"][Math.floor(Math.random()*5)],r:2+Math.random()*4});\n    }\n    function tick(){\n      ctx.clearRect(0,0,120,100);var alive=false;\n      parts.forEach(function(p){p.x+=p.vx;p.y+=p.vy;p.vy+=.3;p.life-=.025;\n        if(p.life>0){alive=true;ctx.beginPath();ctx.arc(p.x,p.y,p.r*p.life,0,6.28);ctx.fillStyle=p.col;ctx.globalAlpha=p.life;ctx.shadowBlur=8;ctx.shadowColor=p.col;ctx.fill();ctx.globalAlpha=1;ctx.shadowBlur=0;}\n      });\n      if(alive)requestAnimationFrame(tick);else ctx.clearRect(0,0,120,100);\n    }\n    tick();\n  });\n})();<\\/script>","explosionBurst");

add("Anime FX","Portal Ring","\n<div style=\"display:flex;justify-content:center;align-items:center;height:130px;\">\n  <div style=\"position:relative;width:100px;height:100px;display:flex;align-items:center;justify-content:center;\">\n    <style>\n      @keyframes pr1{0%{transform:rotateX(70deg) rotate(0deg)}100%{transform:rotateX(70deg) rotate(360deg)}}\n      @keyframes pr2{0%{transform:rotateX(70deg) rotate(120deg)}100%{transform:rotateX(70deg) rotate(480deg)}}\n      @keyframes pr3{0%{transform:rotateX(70deg) rotate(240deg)}100%{transform:rotateX(70deg) rotate(600deg)}}\n    </style>\n    <div style=\"position:absolute;width:80px;height:80px;border-radius:50%;border:3px solid transparent;border-top-color:#00f5d4;border-right-color:#00f5d4;animation:pr1 2s linear infinite;box-shadow:0 0 15px #00f5d4;\"></div>\n    <div style=\"position:absolute;width:60px;height:60px;border-radius:50%;border:3px solid transparent;border-top-color:#7b5cff;border-left-color:#7b5cff;animation:pr2 2.5s linear infinite;box-shadow:0 0 15px #7b5cff;\"></div>\n    <div style=\"position:absolute;width:40px;height:40px;border-radius:50%;border:3px solid transparent;border-bottom-color:#ff2d78;animation:pr3 1.5s linear infinite;box-shadow:0 0 15px #ff2d78;\"></div>\n    <div style=\"width:16px;height:16px;border-radius:50%;background:radial-gradient(circle,#fff,#00f5d4);box-shadow:0 0 20px #00f5d4,0 0 40px rgba(0,245,212,.3);position:relative;z-index:1;\"></div>\n  </div>\n</div>","portalRing");

add("Anime FX","Comet Trail","\n<canvas id=\"XCMT\" width=\"200\" height=\"120\" style=\"width:200px;height:120px;border-radius:12px;background:#07090f;\"></canvas>\n<script>(function(){\n  var c=document.getElementById(\"XCMT\");if(!c)return;\n  var ctx=c.getContext(\"2d\"),W=200,H=120;\n  var comets=[\n    {x:-20,y:30,vx:3.5,vy:.8,trail:[],col:\"#00f5d4\"},\n    {x:-20,y:80,vx:2.8,vy:-.5,trail:[],col:\"#7b5cff\"},\n    {x:-20,y:55,vx:4.2,vy:.3,trail:[],col:\"#ff2d78\"}\n  ];\n  function draw(){\n    ctx.fillStyle=\"rgba(7,9,15,.18)\";ctx.fillRect(0,0,W,H);\n    comets.forEach(function(cm){\n      cm.x+=cm.vx;cm.y+=cm.vy;\n      if(cm.x>W+20){cm.x=-20;cm.y=Math.random()*H*0.8+10;cm.trail=[];}\n      cm.trail.push({x:cm.x,y:cm.y});if(cm.trail.length>25)cm.trail.shift();\n      for(var i=0;i<cm.trail.length;i++){\n        var p=cm.trail[i],a=i/cm.trail.length,r=4*a;\n        ctx.beginPath();ctx.arc(p.x,p.y,r,0,6.28);\n        ctx.fillStyle=cm.col;ctx.globalAlpha=a*.8;ctx.shadowBlur=8*a;ctx.shadowColor=cm.col;ctx.fill();\n      }\n      ctx.globalAlpha=1;ctx.shadowBlur=0;\n      ctx.beginPath();ctx.arc(cm.x,cm.y,4,0,6.28);ctx.fillStyle=\"#fff\";ctx.shadowBlur=15;ctx.shadowColor=cm.col;ctx.fill();ctx.shadowBlur=0;\n    });\n    requestAnimationFrame(draw);\n  }\n  draw();\n})();<\\/script>","cometTrail");


